"""
PEWTER - build hook.

Generates pewter_pkg.vhd:

  C_TE / C_TO : the weave wavetable, 8 row waveforms x 256 samples per
                horizontal period, as even / odd banks (1024 x 8 each) so the
                pixel path reads samples n and n+1 on one clock and
                interpolates.  Bank address = row(3) & (n / 2)(7).
  C_PU / C_PV : metal colourizers, 8 metals x 64 luma steps (512 x 8).
                10-bit chroma divided by 4 (128 = neutral), stored
                U/V-SWAPPED for this hardware (the U register carries Cr).
  C_EXP       : 2^(-i/256) x 65536 (65535 at i = 0), the zoom curve's
                fractional octave (256 x 16).

The wavetable is MEASURED from the reference capture (an analog-synth
picture of brushed-metal tiles woven over rods): the frame repeats every
303.2 px across and 584.4 lines down, in 8 rows of 73 lines.  Each row is
the per-pixel median over its 57 core lines and all ~12 repeats (so the
streak noise averages out), resampled to 256 samples and normalised so
black = 0, the brightest tile = 255.  The streak noise is added back live.
"""

import os

HERE = os.path.dirname(os.path.abspath(__file__))

# 8 rows x 256 samples, raw reference luma (0..255), top row first
TABLE_HEX = [
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
]

# metal chroma knots: (luma, Cb, Cr) in 8-bit BT.601 units (+-112 = full);
# chroma is 0 at black and follows the knots linearly above it.
METALS = [
    ("Pewter",    [(0.16, -5.7, 0.4), (0.50, -9.9, -5.0), (0.90, -14.0, -10.0)]),  # measured
    ("Steel",     [(0.16, 9.0, -4.0), (0.50, 12.0, -6.0), (0.90, 7.0, -4.0)]),
    ("Silver",    [(0.16, 2.0, -1.0), (0.50, 3.0, -1.5), (0.90, 1.5, -0.5)]),
    ("Gold",      [(0.16, -22.0, 15.0), (0.50, -52.0, 22.0), (0.90, -40.0, 9.0)]),
    ("Brass",     [(0.16, -16.0, 4.0), (0.50, -42.0, 7.0), (0.90, -30.0, 1.0)]),
    ("Copper",    [(0.16, -18.0, 22.0), (0.50, -40.0, 38.0), (0.90, -20.0, 28.0)]),
    ("Bronze",    [(0.16, -14.0, 10.0), (0.50, -28.0, 16.0), (0.90, -18.0, 8.0)]),
    ("Verdigris", [(0.16, 7.0, -18.0), (0.50, 13.0, -40.0), (0.90, 6.0, -20.0)]),
]


def table():
    rows = []
    for h in TABLE_HEX:
        raw = [int(h[2 * i:2 * i + 2], 16) for i in range(256)]
        rows.append([max(0, min(255, round((v - 2) * 255 / 238))) for v in raw])
    return rows


def chroma(knots, y):
    pts = [(0.0, 0.0, 0.0)] + knots + [(1.0, knots[-1][1], knots[-1][2])]
    for (y0, b0, r0), (y1, b1, r1) in zip(pts, pts[1:]):
        if y <= y1:
            t = (y - y0) / (y1 - y0)
            return b0 + (b1 - b0) * t, r0 + (r1 - r0) * t
    return pts[-1][1], pts[-1][2]


def palettes():
    pu, pv = [], []
    for _name, knots in METALS:
        for i in range(64):
            cb, cr = chroma(knots, (i + 0.5) / 64)
            # 8-bit units -> 10-bit /4 is the same number; 128 = neutral.
            # U/V swapped: the U register carries Cr.
            pu.append(max(0, min(255, 128 + round(cr))))
            pv.append(max(0, min(255, 128 + round(cb))))
    return pu, pv


def vhd_array(name, vals, typ="t_rom8", digits=2):
    out = ["    constant %s : %s := (" % (name, typ)]
    fmt = 'x"%%0%dX"' % digits
    for i in range(0, len(vals), 16):
        chunk = ", ".join(fmt % v for v in vals[i:i + 16])
        out.append("        " + chunk + ("," if i + 16 < len(vals) else ");"))
    return "\n".join(out)


def main():
    rows = table()
    te, to = [], []
    for r in rows:
        te += r[0::2]
        to += r[1::2]
    pu, pv = palettes()
    ex = [min(65535, round(65536 * 2 ** (-i / 256))) for i in range(256)]
    txt = """-- pewter_pkg.vhd -- GENERATED by pewter.py; edit the generator, not this file.
--
-- C_TE / C_TO: the weave wavetable (8 measured row waveforms x 256 samples
-- per period), even / odd samples, address = row(3) & (n/2)(7).
-- C_PU / C_PV: metal colourizers, address = metal(3) & luma step(6),
-- 10-bit chroma / 4, U/V-SWAPPED (U carries Cr).
-- C_EXP: 2^(-i/256) x 65536 (zoom curve, fractional octave).

library ieee;
use ieee.std_logic_1164.all;

package pewter_pkg is
    type t_rom8 is array(0 to 1023) of std_logic_vector(7 downto 0);
    type t_pal8 is array(0 to 511) of std_logic_vector(7 downto 0);
    type t_exp16 is array(0 to 255) of std_logic_vector(15 downto 0);
%s
%s
%s
%s
%s
end package pewter_pkg;
""" % (vhd_array("C_TE", te), vhd_array("C_TO", to), vhd_array("C_PU", pu, "t_pal8"),
       vhd_array("C_PV", pv, "t_pal8"), vhd_array("C_EXP", ex, "t_exp16", 4))
    with open(os.path.join(HERE, "pewter_pkg.vhd"), "w") as f:
        f.write(txt)


if __name__ == "__main__":
    main()
